#!/bin/sh
# 🪜️ Runs the steps of a steps file one after the other inside ONE capacity grant: steps.sh <memory MB> <steps file>
# A steps file holds one step per line: `<label> <timeout s> <bun flags or -> <script and args…>`; `$G`, `$SP`, `$T` and `$M` expand to the generated folder, the scratchpad, the live suite folder and this folder.
# Every step runs under /usr/bin/time -l with its log in <generated>/<label>.log (resident peak and times at its end). One grant, one process at a time.
# Do not edit this file or the steps file while a run is in flight.
set -u
R=/Users/ueli/Documents/semio
M="$R/.🧬semio/🦑️repo/🎫️tickets/🎆️26/🌙️11/☀️22/GET-STAFFAGE-RUNNING-END-TO-END-AND-FINISH-ALL-STAFFAGE-TICKETS/🧰️matrix/MM"
BUN=$(ls ~/Library/Caches/semio/runtimes/bun/*/bun | head -1)
if [ "${1:-}" != "--inside" ]; then
  cd "$R" || exit 1
  exec repo capacity run --memory="$1" -- sh "$M/steps.sh" --inside "$2"
fi
G="$R/.🧬semio/🦑️repo/🎫️tickets/🎆️26/🌙️11/☀️22/GET-STAFFAGE-RUNNING-END-TO-END-AND-FINISH-ALL-STAFFAGE-TICKETS/🗑️generated/matrix/MM"
SP="${SP:-/private/tmp/claude-501/-Users-ueli-Documents-semio/77b365fc-dfc7-4b6f-9d54-4f0eb23231c9/scratchpad}"
T="$R/🎓️teaching/🏛️architecture/🧍️staffage/🧪️tests/🔭️multiview-coverage"
mkdir -p "$G"
cd "$R" || exit 1
while read -r label limit flags rest; do
  [ -z "$label" ] && continue
  [ "$flags" = "-" ] && flags=""
  started=$(date +%s)
  eval "/usr/bin/time -l timeout $limit \"$BUN\" $flags $rest" > "$G/$label.log" 2>&1
  echo "exit $?, $(( $(date +%s) - started )) s" >> "$G/$label.log"
  echo "$label: $(grep -E 'maximum resident| real |^exit' "$G/$label.log" | tr -s ' ' | tr '\n' ';')"
done < "$2"
